tape( 'the function computes one DQDS transform in ping-pong form', function test( t ) {
	var strideOut;
	var offsetOut;
	var expectedZ;
	var expected;
	var strideZ;
	var offsetZ;
	var SIGMA;
	var data;
	var IEEE;
	var EPS;
	var out;
	var TAU;
	var I0;
	var N0;
	var PP;
	var Z;

	data = PING;

	I0 = data.I0;
	N0 = data.N0;
	Z = new Float64Array( data.Z );
	strideZ = data.strideZ;
	offsetZ = data.offsetZ;
	PP = data.PP;
	TAU = data.TAU;
	SIGMA = data.SIGMA;
	EPS = data.EPS;
	IEEE = true;
	strideOut = data.strideOut;
	offsetOut = data.offsetOut;

	out = new Float64Array( 6 );

	expected = new Float64Array( data.expectedOut );
	expectedZ = new Float64Array( data.Z_out );
	expectedZ = new Float64Array( data.Z_out );

	dlasq5( I0, N0, Z, strideZ, offsetZ, PP, TAU, SIGMA, IEEE, EPS, out, strideOut, offsetOut );
	t.strictEqual( isAlmostEqual( out, expected, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( Z, expectedZ, 1 ), true, 'returns expected value' );

	Z = new Float64Array( data.Z );
	IEEE = false;

	out = new Float64Array( 6 );
	dlasq5( I0, N0, Z, strideZ, offsetZ, PP, TAU, SIGMA, IEEE, EPS, out, strideOut, offsetOut );
	t.strictEqual( isAlmostEqual( out, expected, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( Z, expectedZ, 1 ), true, 'returns expected value' );

	data = PONG;

	I0 = data.I0;
	N0 = data.N0;
	Z = new Float64Array( data.Z );
	strideZ = data.strideZ;
	offsetZ = data.offsetZ;
	PP = data.PP;
	TAU = data.TAU;
	SIGMA = data.SIGMA;
	EPS = data.EPS;
	IEEE = true;
	strideOut = data.strideOut;
	offsetOut = data.offsetOut;

	out = new Float64Array( 6 );

	expected = new Float64Array( data.expectedOut );
	expectedZ = new Float64Array( data.Z_out );

	dlasq5( I0, N0, Z, strideZ, offsetZ, PP, TAU, SIGMA, IEEE, EPS, out, strideOut, offsetOut );
	t.strictEqual( isAlmostEqual( out, expected, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( Z, expectedZ, 1 ), true, 'returns expected value' );

	Z = new Float64Array( data.Z );
	IEEE = false;

	out = new Float64Array( 6 );
	dlasq5( I0, N0, Z, strideZ, offsetZ, PP, TAU, SIGMA, IEEE, EPS, out, strideOut, offsetOut );
	t.strictEqual( isAlmostEqual( out, expected, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( Z, expectedZ, 1 ), true, 'returns expected value' );
	t.end();
});

